// One row per ticket, keys matching the sheet's header text exactly so the
// Sheets node can auto-map. Monday is the authority on whether something is
// finished - Brian works the board, not the database - so Status and Completed
// come from there, with Postgres resolved_at preferred for the date once the
// nightly reconcile has stamped it (it's exact; Monday's updated_at only
// approximates when the item was ticked).

const monday = $('Pull Monday Board').first().json?.data?.boards?.[0]?.groups?.[0]?.items_page?.items || [];
const ledger = $input.all().map(i => i.json);

const col = (item, id) => (item.column_values.find(c => c.id === id)?.text || '').trim();

const byTicket = {};
for (const it of monday) {
  const tid = col(it, 'text_mm5vaz0');
  if (tid) byTicket[tid] = { id: it.id, status: col(it, 'project_status'), updated_at: it.updated_at };
}

const day = v => v ? new Date(v).toISOString().slice(0, 10) : '';
const stamp = v => v ? new Date(v).toISOString().slice(0, 16).replace('T', ' ') : '';
const now = new Date().toISOString().slice(0, 16).replace('T', ' ');

return ledger.map(t => {
  const m = byTicket[t.ticket_id] || null;
  const status = m ? (m.status || 'Not Started') : (t.status === 'resolved' ? 'Done' : 'Not on board');
  const done = status === 'Done';
  const completed = done ? day(t.resolved_at || (m && m.updated_at)) : '';

  return { json: {
    'Ticket ID':   t.ticket_id,
    'Submitted':   stamp(t.created_at),
    'Venue':       t.venue || '',
    'Gear':        t.gear_item || '',
    'Category':    t.category || '',
    'Severity':    t.severity || '',
    'Summary':     t.summary || '',
    'Already Tried': t.troubleshooting || '',
    'Reported By': t.submitter_name || '',
    'Contact':     '',
    'Photos':      Number(t.photo_count || 0) || '',
    'Monday Item': m ? `https://3cdc-cast.monday.com/boards/18405931866/pulses/${m.id}`
                     : (t.monday_item_id ? `https://3cdc-cast.monday.com/boards/18405931866/pulses/${t.monday_item_id}` : ''),
    'Status':      status,
    'Completed':   completed,
    // Once it's finished this is how long it actually took; until then it's how
    // long it has been sitting.
    'Days Open':   Number(t.days_open ?? 0),
    'Last Synced': now
  }};
});
